edge_probe:
use mio::{net::UdpSocket, Events, Interest, Poll, Token};
use std::{env, io, net::UdpSocket as Sender, time::{Duration, Instant}};

fn edge(poll: &mut Poll, token: Token, wait: Duration) -> io::Result<(bool, bool)> {
    let mut events = Events::with_capacity(8);
    let until = Instant::now()+wait;
    loop {
        poll.poll(&mut events, Some(until.saturating_duration_since(Instant::now())))?;
        let mut flags=(false,false);
        for ev in &events {
            assert_eq!(ev.token(),token);
            flags.0 |= ev.is_readable();
            flags.1 |= ev.is_writable();
        }
        if flags.0 || flags.1 || Instant::now()>=until {return Ok(flags)}
    }
}
fn empty(s:&UdpSocket) {
    assert_eq!(s.recv_from(&mut [0;4]).unwrap_err().kind(),io::ErrorKind::WouldBlock);
}
fn main()->io::Result<()> {
    let expected=env::args().nth(1).unwrap()=="base";
    let mut poll=Poll::new()?;
    let mut socket=UdpSocket::bind("127.0.0.1:0".parse().unwrap())?;
    let sender=Sender::bind("127.0.0.1:0")?;
    sender.set_read_timeout(Some(Duration::from_secs(1)))?;
    let both=Interest::READABLE|Interest::WRITABLE;
    let long=Duration::from_secs(1);
    let short=Duration::from_millis(12);
    let mut repeated=0;
    for pass in 0..20 {
        let t=Token(2*pass);
        if pass==0 {poll.registry().register(&mut socket,t,both)?}
        else {poll.registry().reregister(&mut socket,t,both)?}
        assert_eq!(edge(&mut poll,t,long)?,(false,true));
        empty(&socket);
        let (read,write)=edge(&mut poll,t,short)?;
        assert!(!read);assert_eq!(write,expected);
        repeated+=usize::from(write);
        // Exercise the ordinary send's WouldBlock rearm deterministically.
        let result=socket.try_io(|| Err::<(),_>(io::Error::from(io::ErrorKind::WouldBlock)));
        assert_eq!(result.unwrap_err().kind(),io::ErrorKind::WouldBlock);
        empty(&socket); // The read must leave the outstanding writer armed.
        assert!(edge(&mut poll,t,long)?.1);
        sender.send_to(&[pass as u8],socket.local_addr()?)?;
        assert!(edge(&mut poll,t,long)?.0);
        let (n,peer)=socket.recv_from(&mut [0;4])?;
        assert_eq!(n,1);assert_eq!(peer,sender.local_addr()?);
        assert_eq!(socket.send_to(b"ok",peer)?,2);
        assert_eq!(sender.recv_from(&mut [0;4])?.0,2);
        let read=Token(2*pass+1);
        poll.registry().reregister(&mut socket,read,Interest::READABLE)?;
        empty(&socket);
        assert_eq!(edge(&mut poll,read,short)?,(false,false));
        sender.send_to(b"r",socket.local_addr()?)?;
        assert_eq!(edge(&mut poll,read,long)?,(true,false));
        assert_eq!(socket.recv_from(&mut [0;4])?.0,1);
    }
    println!("dry receives 20, unsolicited writable edges {repeated}, writer rearmed 20, read-only interest and reuse 20");
    Ok(())
}

